        { type: "visual_layout_map", filename: `${projectSlug}_Visual_Layout_Map.png`, mimeType: "image/png", data: layoutMap },
        { type: "comic_storyboard", filename: `${projectSlug}_Comic_Storyboard.png`, mimeType: "image/png", data: storyboard }
